with with_windows as (select *, count(cost) over (partition by order_id order by delivered_date asc, id asc rows between 2 preceding and current row) as last3_count_cost, avg(cost) over (partition by order_id order by delivered_date asc, id asc rows between 2 preceding and current row) as last3_avg_cost, min(cost) over (partition by order_id order by delivered_date asc, id asc rows between 2 preceding and current row) as last3_min_cost, sum(cost) over (partition by order_id order by delivered_date asc, id asc rows between 2 preceding and current row) as last3_sum_cost, round(cost / sum(cost) over (partition by order_id, carrier), 4) as cost_share from shipments) select id, order_id, carrier, shipped_date, delivered_date, cost, status, last3_count_cost, last3_avg_cost from with_windows order by cost asc nulls last
